import {getWalletSession,networkLabel} from './wallet-session.mjs?v=36';
const wallet=getWalletSession(),buttons=[...document.querySelectorAll('[data-wallet-open]')];
const short=address=>address.slice(0,6)+'…'+address.slice(-4);
const dialog=document.createElement('dialog');dialog.className='wallet-dialog';dialog.setAttribute('aria-labelledby','walletTitle');
dialog.innerHTML='<div class="wallet-heading"><span>GETAWAY / WALLET</span><button type="button" class="wallet-close" aria-label="Close wallet panel">×</button></div><div class="wallet-body"><h2 id="walletTitle">CONNECT YOUR WALLET</h2><p id="walletIntro">Choose a wallet to connect to GETAWAY.</p><div id="walletContent"></div><p id="walletNotice" class="wallet-notice" role="status" aria-live="polite"></p><div class="wallet-launch"><b>GETAWAY / TESTNET WORKSHOP</b><p>Try burns with free test tokens on Robinhood Chain Testnet. Mainnet burns are not enabled.</p><a href="/testnet/">OPEN TESTNET SETUP</a></div></div>';
document.body.appendChild(dialog);let opener=null,providerSignature='',view='';
const $=id=>dialog.querySelector('#'+id),notice=text=>$('walletNotice').textContent=text;
function button(label,action,className='wallet-action'){const b=document.createElement('button');b.type='button';b.className=className;b.textContent=label;b.addEventListener('click',action);return b;}
async function copy(text,label){try{await navigator.clipboard.writeText(text);notice(label);}catch{notice('Copy is unavailable here. Select and copy the address shown above.');}}
function render(){const state=wallet.state();for(const b of buttons){b.textContent=state.account?short(state.account):state.status==='connecting'?'CONNECTING…':'CONNECT WALLET';b.classList.toggle('wallet-connected',!!state.account);b.setAttribute('aria-label',state.account?'Open connected wallet '+state.account:'Connect wallet');b.setAttribute('aria-expanded',String(dialog.open));}
 if(!dialog.open)return;const connected=state.status==='connected',nextView=connected?'connected':'picker',list=wallet.list(),signature=nextView+':'+list.map(p=>p.id+':'+p.name).join('|');
 $('walletTitle').textContent=connected?'YOUR WALLET':'CONNECT YOUR WALLET';$('walletIntro').textContent=connected?'Connected to GETAWAY.':state.status==='connecting'?'Approve the connection in '+state.walletName+'.':'Choose a wallet to connect. This only shares your public address.';
 if(signature!==providerSignature||view!==nextView){providerSignature=signature;view=nextView;const content=$('walletContent');content.replaceChildren();
  if(connected){const name=document.createElement('p');name.id='walletName';name.className='wallet-name';const address=document.createElement('code');address.id='walletAddress';address.className='wallet-address';const network=document.createElement('div');network.id='walletNetwork';network.className='wallet-network';const actions=document.createElement('div');actions.className='wallet-actions';actions.append(button('COPY ADDRESS',()=>copy(wallet.state().account,'Wallet address copied.')),button('DISCONNECT',()=>{wallet.disconnect();notice('Disconnected from GETAWAY on this browser.');},'wallet-action wallet-disconnect'));content.append(name,address,network,actions);
  }else{const options=document.createElement('div');options.className='wallet-options';for(const provider of list){const b=button('',()=>wallet.connect(provider.id),'wallet-provider');b.dataset.provider=provider.id;const icon=document.createElement('span');icon.className='wallet-provider-icon';icon.textContent=provider.name.slice(0,1).toUpperCase();if(/^data:image\/(png|webp|jpeg|gif|svg\+xml)[;,]/i.test(provider.icon)&&provider.icon.length<200000){const img=document.createElement('img');img.src=provider.icon;img.alt='';img.width=32;img.height=32;icon.replaceChildren(img);}const label=document.createElement('strong');label.textContent=provider.name;const meta=document.createElement('span');meta.className='wallet-provider-meta';meta.textContent='DETECTED';b.append(icon,label,meta);options.appendChild(b);}content.appendChild(options);
   if(!list.length){const empty=document.createElement('div');empty.className='wallet-empty';const title=document.createElement('strong');title.textContent='NO WALLET DETECTED';const text=document.createElement('p');text.textContent='Use a browser with a wallet extension, or open this site in your mobile wallet’s browser.';const url=document.createElement('code');url.className='wallet-site-url';url.textContent=location.origin;empty.append(title,text,url,button('COPY SITE LINK',()=>copy(location.origin,'Site link copied. Open it in your wallet browser.')));content.appendChild(empty);}
   const help=document.createElement('div');help.className='wallet-help';help.append(button('CHECK FOR WALLETS',()=>{wallet.scan();render();},'wallet-text-button'));const install=document.createElement('a');install.href='https://metamask.io/download/';install.target='_blank';install.rel='noopener noreferrer';install.textContent='GET METAMASK';help.appendChild(install);content.appendChild(help);
  }
 }
 if(connected){$('walletName').textContent=state.walletName;$('walletAddress').textContent=state.account;$('walletNetwork').textContent=networkLabel(state.chainId)+' · '+state.chainId;}
 for(const b of dialog.querySelectorAll('[data-provider]'))b.disabled=state.status==='connecting';notice(state.error||(state.status==='connecting'?'Waiting for your wallet…':''));
}
function open(event){opener=event.currentTarget;providerSignature='';dialog.showModal();wallet.scan();render();dialog.querySelector('.wallet-close').focus();}
function close(){dialog.close();opener?.focus();}
for(const b of buttons){b.setAttribute('aria-haspopup','dialog');b.addEventListener('click',open);}
dialog.querySelector('.wallet-close').addEventListener('click',close);dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)close();}});dialog.addEventListener('close',render);wallet.subscribe(render);
